import sys
from collections import defaultdict, deque

def read_input():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    edges = []
    index = 1
    for _ in range(n - 1):
        a = int(data[index])
        b = int(data[index + 1])
        edges.append((a, b))
        index += 2

    return n, edges

def bfs(tree, start):
    queue = deque([start])
    visited = {start}
    parent = {start: None}
    level = {start: 0}

    while queue:
        node = queue.popleft()
        for neighbor in tree[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                parent[neighbor] = node
                level[neighbor] = level[node] + 1
                queue.append(neighbor)

    return parent, level

def find_heaviest_subtree(tree, root):
    parent, level = bfs(tree, root)

    def dfs(node):
        size = 1
        max_subtree_size = 0
        for neighbor in tree[node]:
            if neighbor != parent[node]:
                subtree_size = dfs(neighbor)
                size += subtree_size
                max_subtree_size = max(max_subtree_size, subtree_size)
        return size, max_subtree_size

    total_size, _ = dfs(root)
    return total_size

