    parent, level = bfs(tree, root)

    def dfs(node):
        size = 1
        max_subtree_size, best_child = 0, None
        for neighbor in tree[node]:
            if neighbor != parent[node]:
                subtree_size = dfs(neighbor)
                size += subtree_size
                if subtree_size > max_subtree_size:
                    max_subtree_size = subtree_size
                    best_child = neighbor

        if size - max_subtree_size > max_subtree_size:
            return node, best_child
        else:
            return None, None

    return dfs(root)

def main():
    n, edges = read_input()

    tree = defaultdict(list)
    for a, b in edges:
        tree[a].append(b)
        tree[b].append(a)

    transformations = []

    for _ in range(2 * n):
        root = 1
        heavy_subtree_size = find_heaviest_subtree(tree, root)

        if heavy_subtree_size <= n // 2:
